    public void processOperation(METVendSiteLeadTimeUpdContract _contract)
    {
        RecId metVendSiteSettingsSetupRecId = _contract.parmRecId();
        ReqItemTable reqItemTable;
        METVendSiteSettingsSetup metVendSiteSettingsSetup = metVendSiteSettingsSetup::find(metVendSiteSettingsSetupRecId);
        METVendParameters METVendParameters = METVendParameters::find();
        InventDim inventDim;

        if (metVendSiteSettingsSetup)
        {           
            ttsbegin;

            reqItemTable.skipDataMethods(true);
            reqItemTable.skipDatabaseLog(true);
            
            if (_contract.parmIsLevelZero() == NoYes::Yes)
            {
                // If Level 0 then update all items for this vendor and coverage group                
                update_recordset reqItemTable setting
                    LeadTimePurchase = metVendSiteSettingsSetup.DefaultItemCovLeadTime,
                    LeadTimePurchaseActive = NoYes::Yes
                where reqItemTable.VendId == metVendSiteSettingsSetup.AssignedVendorAccount
                    && reqItemTable.reqGroupId == METVendParameters.DefaultCoverageGroup;
            }
            else
            {   
                if (metVendSiteSettingsSetup.AssignedVendorAccount && 
                    metVendSiteSettingsSetup.AssignedSite && 
                    metVendSiteSettingsSetup.AssignedWH == '')
                {
                    // Update level 1
                    update_recordset reqItemTable setting
                        LeadTimePurchase = metVendSiteSettingsSetup.DefaultItemCovLeadTime,
                        LeadTimePurchaseActive = NoYes::Yes
                            where reqItemTable.VendId == metVendSiteSettingsSetup.AssignedVendorAccount
                                && reqItemTable.reqGroupId == METVendParameters.DefaultCoverageGroup
                    exists join inventDim
                        where inventDim.inventDimId == reqItemTable.CovInventDimId
                        && inventDim.inventSiteId == metVendSiteSettingsSetup.AssignedSite
                        && inventDim.InventLocationId == '';
                } 
                else if (metVendSiteSettingsSetup.AssignedVendorAccount && metVendSiteSettingsSetup.AssignedSite && metVendSiteSettingsSetup.AssignedWH)
                {
                    // Update level 2
                    update_recordset reqItemTable setting
                        LeadTimePurchase = metVendSiteSettingsSetup.DefaultItemCovLeadTime,
                        LeadTimePurchaseActive = NoYes::Yes
                            where reqItemTable.VendId == metVendSiteSettingsSetup.AssignedVendorAccount
                                && reqItemTable.reqGroupId == METVendParameters.DefaultCoverageGroup
                    exists join inventDim
                        where inventDim.inventDimId == reqItemTable.CovInventDimId
                        && inventDim.inventSiteId == metVendSiteSettingsSetup.AssignedSite
                        && inventDim.InventLocationId == metVendSiteSettingsSetup.AssignedWH;
                }
            }
            ttscommit;

        }
    }
